-- Patient Safety & Quality Improvement: Part 7 (Questions 301-350)
-- US MD / MBBS / USMLE Step 3
-- Target: Supabase (PostgreSQL)
-- Topic Slug: ethics-patient-safety

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-patient-safety' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ethics-patient-safety not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- ETHICAL PRINCIPLES
    (v_topic_id, 'Which ethical principle is most directly related to the goal of "Patient Safety"?', '["Beneficence", "Non-maleficence", "Autonomy", "Justice"]', 1, 'Non-maleficence ("First, do no harm") is the foundational ethical principle for patient safety.'),
    (v_topic_id, 'The ethical principle of "Autonomy" is best protected through:', '["Informed consent and respecting patient choices", "Providing the most expensive care", "Doing what the doctor thinks is best", "Ensuring all patients have a private room"]', 0, 'Autonomy recognizes the patient''s right to self-determination.'),
    (v_topic_id, 'Which principle requires that healthcare resources be distributed fairly across a population?', '["Autonomy", "Non-maleficence", "Justice", "Fidelity"]', 2, 'Distributive justice is a core concern in health systems and quality improvement.'),
    (v_topic_id, '"Beneficence" refers to the clinician''s duty to:', '["Avoid causing harm", "Act in the best interest of the patient", "Follow the law", "Respect the patient''s secrets"]', 1, 'Beneficence is the positive duty to provide benefit and promote the patient''s well-being.'),
    (v_topic_id, 'When a patient''s wishes conflict with the doctor''s clinical recommendation, which principle typically takes precedence in US law (if the patient has capacity)?', '["Beneficence", "Autonomy", "Justice", "Non-maleficence"]', 1, 'In most cases, a competent patient''s autonomy (their right to refuse treatment) is respected even if it is not in their best medical interest.'),

    -- DISCLOSURE & APOLOGY
    (v_topic_id, 'The American Medical Association (AMA) Code of Medical Ethics states that when an error occurs, the physician should:', '["Wait to see if the patient asks", "Inform the patient of all relevant facts", "Only tell the patient if the error was \"major\"", "Conceal the error to prevent loss of trust"]', 1, 'The AMA and most professional organizations mandate full and honest disclosure of errors that reach the patient.'),
    (v_topic_id, 'A "Full Apology" after an error should include an expression of regret, an acknowledgment of the error, and:', '["A promise that it will never happen again (if true)", "A statement about who is being fired", "A bill for the investigation", "A request that the patient not sue"]', 0, 'A sincere apology should be focused on the patient''s needs and the commitment to future safety.'),
    (v_topic_id, 'In some states, "Apology Laws" make it so that an expression of regret __________ be used as evidence in a malpractice trial.', '["Always", "Cannot (to encourage honesty and empathy)", "Must", "Can only"]', 1, 'These laws aim to reduce the fear of litigation as a barrier to honest communication.'),
    (v_topic_id, 'If a resident makes a mistake, who has the primary responsibility for disclosing the error to the patient?', '["The resident alone", "The medical student", "The attending physician (senior clinician)", "The hospital lawyer"]', 2, 'While the team may be involved, the ultimate responsibility for disclosure lies with the attending of record.'),
    (v_topic_id, 'Should "Near Misses" (errors that did not reach the patient) be disclosed to the patient?', '["Yes, always", "No, it is generally not required and may cause unnecessary anxiety", "Only if the patient asks", "Only if the doctor is feeling guilty"]', 1, 'While near misses MUST be reported internally for QI, they are typically NOT disclosed to patients unless the "near-miss" itself was distressing (e.g., stopping a surgery after anesthesia was started).'),

    -- PROFESSIONALISM & IMPAIRMENT
    (v_topic_id, 'What is the most appropriate action if you suspect a colleague is practicing while impaired by substance use?', '["Talk to them and tell them to stop", "Ignore it to avoid \"snitching\"", "Report the concern to your supervisor or the state''s Physician Health Program (PHP)", "Wait for them to make a mistake"]', 2, 'Reporting is a professional duty to protect current and future patients from harm.'),
    (v_topic_id, 'A "Physician Health Program" (PHP) is designed to:', '["Punish doctors who make errors", "Provide a confidential pathway for evaluation, treatment, and monitoring of impaired clinicians", "Collect hospital statistics", "Pay for medical school"]', 1, 'PHPs support the clinician while ensuring public safety through rigorous monitoring.'),
    (v_topic_id, 'Which of the following is a "Boundary Violation" in the doctor-patient relationship?', '["Giving the patient a ride home in your personal car", "Having a romantic relationship with a current patient", "Accepting an expensive gift", "All of the above"]', 3, 'Maintaining professional boundaries is essential for the integrity of the relationship and the safety of the patient.'),
    (v_topic_id, 'If a physician is offered a "kickback" from a pharmaceutical company for prescribing a specific drug, they are facing a:', '["Conflict of interest", "Promotion opportunity", "Just Culture issue", "Technical error"]', 0, 'Conflicts of interest can bias clinical judgment and compromise patient safety and trust.'),
    (v_topic_id, 'The primary mechanism for dealing with a "Conflict of Interest" (e.g., in a research study) is:', '["Ignoring it", "Full disclosure/Transparency", "Giving the money back", "Firing the doctor"]', 1, 'Transparency allows others to evaluate the potential bias in the information provided.'),

    -- REGULATORY BODIES & LAWS
    (v_topic_id, 'Which federal agency is responsible for the safety and efficacy of medical devices and medications?', '["CDC", "FDA (Food and Drug Administration)", "CMS", "The Joint Commission"]', 1, 'The FDA regulates drugs, devices, and biologics.'),
    (v_topic_id, 'The Joint Commission (TJC) performs "Accreditation Surveys" primarily to:', '["Collect taxes", "Assess whether a hospital meets established quality and safety standards", "Rank hospitals by their profit", "Audit the hospital''s electricity use"]', 1, 'TJC accreditation is essential for most hospitals to receive reimbursement from Medicare/Medicaid.'),
    (v_topic_id, 'The "EMTALA" law (Emergency Medical Treatment and Labor Act) requires hospitals to:', '["Give free care to everyone forever", "Provide a medical screening exam and stabilization to anyone presenting to the ED, regardless of their ability to pay", "Charge the same price to every patient", "Only treat citizens"]', 1, 'EMTALA is a fundamental "safety net" law to prevent "patient dumping."'),
    (v_topic_id, 'Which federal agency administers the Medicare and Medicaid programs and sets the "Conditions of Participation" for safety?', '["FDA", "CMS (Centers for Medicare & Medicaid Services)", "NIH", "OSHA"]', 1, 'CMS is the largest payer in the US and uses its financial leverage to drive quality and safety standards.'),
    (v_topic_id, 'OSHA (Occupational Safety and Health Administration) is primarily concerned with the safety of:', '["The patients", "The healthcare workers", "The hospital board", "The local environment"]', 1, 'OSHA regulates workplace safety, including needle-stick protection and PPE.'),

    -- PATIENT RIGHTS & CONFIDENTIALITY
    (v_topic_id, 'The HIPAA law (Health Insurance Portability and Accountability Act) is designed to protect:', '["Patient insurance coverage", "The privacy and security of patient health information", "The hospital from lawsuits", "The doctor''s salary"]', 1, 'HIPAA mandates strict controls on who can access and share patient data.'),
    (v_topic_id, 'Under HIPAA, when is it permissible to share a patient''s protected health information (PHI) without their explicit consent?', '["For the purposes of Treatment, Payment, or Healthcare Operations (TPO)", "To tell a funny story at a party", "To post on social media (with the name removed but the photo visible)", "When a neighbor asks"]', 0, 'TPO allows for the necessary flow of information for the care of the patient.'),
    (v_topic_id, 'If a patient requests to see their own medical record, the hospital:', '["Can refuse for any reason", "Must provide access (though they can charge a reasonable fee for copying)", "Must provide it for free within 5 minutes", "Can only show it to the patient''s lawyer"]', 1, 'Patients have a legal right to access and amend their health records under HIPAA.'),
    (v_topic_id, 'A "Sentinel Event" involving a patient suicide in a 24-hour care facility must be reported to:', '["The Police", "The Joint Commission (TJC) and often state licensing bodies", "The local newspaper", "The patient''s employer"]', 1, 'Reporting is part of the regulatory oversight for serious safety failures.'),
    (v_topic_id, '"Patient Rights" include the right to:', '["Refuse treatment", "Participate in their care plan", "Have their advance directives followed", "All of the above"]', 3, 'Respecting patient rights is a core component of a high-quality health system.'),

    -- TRIAGE & RESOURCE ALLOCATION
    (v_topic_id, 'In a "Mass Casualty Incident" (MCI), the goal of triage is to:', '["Provide the most intensive care to the sickest patient", "Do the greatest good for the greatest number of people", "Treat the youngest patients first", "Treat the people with the best insurance first"]', 1, 'Utilitarian ethics (Justice) drives MCI triage to maximize the survival of the population.'),
    (v_topic_id, 'The "Black Tag" in MCI triage (e.g., START triage) indicates a patient who is:', '["Critically ill and needs immediate care", "Stable and can wait", "Deceased or has injuries incompatible with life given current resources", "Only minorly injured"]', 2, 'Patients who cannot be saved are prioritized lower during an MCI to save others.'),
    (v_topic_id, '"Red Tag" in MCI triage indicates a patient who:', '["Needs immediate, life-saving intervention (e.g., airway obstruction, tension pneumothorax)", "Is already dead", "Is walking around", "Has a minor cut"]', 0, 'Red tags are the highest priority for treatment and transport.'),
    (v_topic_id, 'Which ethical principle is challenged during a ventilator shortage (e.g., during a pandemic)?', '["Autonomy", "Justice (Fair allocation of scarce resources)", "Beneficence", "Fidelity"]', 1, 'Allocation of scarce resources requires transparent, ethical frameworks to ensure fairness.'),
    (v_topic_id, 'True or False: A patient''s "Social Worth" (e.g., being a celebrity or a CEO) should be a factor in medical triage decisions.', '["True", "False"]', 1, 'Triage is based on clinical need and the potential to benefit, not on social or economic status.'),

    -- END OF LIFE & ADVANCE DIRECTIVES
    (v_topic_id, 'A "Living Will" is a document that:', '["Tells the family who gets the patient''s money", "Specifies the types of medical treatment the patient does or does not want at the end of life", "Appoints a person to make decisions for the patient", "Is only valid if a lawyer signed it"]', 1, 'Living wills provide specific instructions for care.'),
    (v_topic_id, 'A "Medical Power of Attorney" (Durable Power of Attorney for Healthcare) is a person who:', '["Is a lawyer", "Is designated by the patient to make medical decisions if the patient loses capacity", "Can override the patient''s living will", "Must be a blood relative"]', 1, 'The surrogate (or proxy) should make decisions based on the patient''s "substituted judgment" (what the patient would have wanted).'),
    (v_topic_id, 'If a patient has a "DNR" (Do Not Resuscitate) order and their heart stops, the appropriate action is to:', '["Perform CPR anyway", "Withhold chest compressions and intubation, but continue other comfort-focused care", "Leave the room", "Call the police"]', 1, 'A DNR applies only to cardiac or respiratory arrest; it does not mean "do not treat."'),
    (v_topic_id, 'If a patient''s wishes are unknown and no surrogate is available, what is the default ethical and legal standard?', '["Do nothing", "Proceed with life-sustaining treatment (the \"Presumption of Life\")", "Ask a random person in the hallway", "Wait for a court order"]', 1, 'When in doubt, clinicians should act to preserve life until more information is available.'),
    (v_topic_id, 'What is the "Double Effect" principle in palliative care?', '["Charging the patient twice", "The ethical justification for providing high doses of pain medication that may hasten death as an unintended side effect", "When a treatment cures two diseases", "When an error is made by two people"]', 1, 'The primary intent must be to relieve suffering, not to cause death.'),

    -- MISC ETHICS & SAFETY
    (v_topic_id, 'Which organization maintains the "MedWatch" system for reporting adverse events related to medical products?', '["CDC", "FDA", "The Joint Commission", "AMA"]', 1, 'MedWatch is the FDA''s safety information and adverse event reporting program.'),
    (v_topic_id, 'The "Placebo Effect" is an example of which phenomenon?', '["A medication error", "The powerful influence of patient expectation and the clinician-patient relationship on healing", "A technical failure", "Insurance fraud"]', 1, 'Ethics require that placebos not be used deceptively in clinical practice.'),
    (v_topic_id, 'Which document outlines the professional obligations of a physician in the US?', '["The US Constitution", "The AMA Code of Medical Ethics", "The Hospital Employee Manual", "The patient''s chart"]', 1, 'The AMA Code is the "gold standard" for professional ethics in the US.'),
    (v_topic_id, 'What is "Clinical Governance"?', '["The hospital board''s political party", "The framework through which organizations are accountable for continuously improving the quality of their services", "A type of software", "The insurance company''s rules"]', 1, 'Governance ensures that safety is managed at the highest organizational level.'),
    (v_topic_id, 'A "Root Cause Analysis" is an example of an organization fulfilling its duty of:', '["Transparency and Accountability", "Cost-cutting", "Advertising", "Hiring"]', 0, 'RCA demonstrates that the organization takes its responsibility for patient safety seriously.'),

    -- FINAL BATCH OF QUESTIONS
    (v_topic_id, 'If a patient is a minor and their parents refuse a life-saving blood transfusion for religious reasons, the physician should:', '["Respect the parents'' autonomy", "Seek a court order to provide the treatment (the \"Parens Patriae\" doctrine)", "Ignore the parents and do it anyway", "Discharge the patient"]', 1, 'The state has an interest in protecting the life of a minor; parental autonomy is not absolute in life-threatening situations.'),
    (v_topic_id, 'A "Near Miss" is also known as a:', '["Close call", "Good catch", "Potential adverse event", "All of the above"]', 3, 'These terms all describe a system failure that was intercepted.'),
    (v_topic_id, 'Which of the following is a "Structural" factor in patient safety?', '["Hand hygiene compliance", "The presence of a computerized order entry system", "The patient''s mortality rate", "The time-out process"]', 1, 'Technology (like CPOE) is a structural attribute.'),
    (v_topic_id, 'The "Swiss Cheese Model" focuses on __________ failures.', '["Individual", "Organizational/Systems", "Surgical", "Mechanical"]', 1, 'Reason''s model is the foundation of the Systems Approach.'),
    (v_topic_id, 'What is the "First Rule" of healthcare?', '["Primum non nocere (First, do no harm)", "The customer is always right", "Profit is priority", "More tests are better"]', 0, 'Non-maleficence remains the primary ethical command.'),
    (v_topic_id, 'A "Never Event" is typically __________.', '["Unpreventable", "Unambiguous and serious", "Inexpensive", "Common"]', 1, 'The unambiguous nature of these events makes them perfect markers for system failure.'),
    (v_topic_id, 'In a "Just Culture," human error is viewed as __________.', '["A failure of character", "A symptom of a system problem", "A reason for firing", "An intentional act"]', 1, 'The focus is on why the person made the error, not the error itself.'),
    (v_topic_id, 'The "Best" way to prevent medical errors is to:', '["Hire only the best people", "Design systems that make the right way easy and the wrong way hard", "Increase the number of lawsuits", "Write more rules"]', 1, 'Design (human factors) is stronger than discipline or policy.'),
    (v_topic_id, 'If you see a colleague not washing their hands before entering a room, you should:', '["Ignore it", "Report them to the board", "Briefly and professionally remind them (\"Peer-to-peer accountability\")", "Tell the patient"]', 2, 'Low-level, professional reminders are a hallmark of a healthy safety culture.'),
    (v_topic_id, 'Patient safety is ultimately the responsibility of:', '["The nurses", "The doctors", "The administration", "Everyone in the healthcare organization"]', 3, 'Safety is a collective, organizational responsibility.');
END $$;
